/* lazysite-app.js (SM1155): registers the app's service worker.
 *
 * The engine adds this script to a page inside an app's scope, with the worker's
 * address and scope as data attributes. The worker itself is generated by the
 * engine (lazysite-processor/app.pm); this only asks the browser to install it.
 * It reads nothing from the page, stores nothing, and a browser without service
 * workers, or a refusal, leaves the page exactly as it was. */
(function () {
  'use strict';
  if (!('serviceWorker' in navigator)) return;
  var s = document.querySelector('script[data-ls-app-sw]');
  if (!s) return;
  var sw = s.getAttribute('data-ls-app-sw');
  var scope = s.getAttribute('data-ls-app-scope');
  if (!sw || !scope) return;
  navigator.serviceWorker.register(sw, { scope: scope }).catch(function () {});
})();
